cd /work/workspace && python3 << 'EOF'
import csv, json
from collections import defaultdict

rows = list(csv.DictReader(open('documents/bank_operating_q1.csv')))
print("rows:", len(rows))
# verify running balance and header totals
start = 212440.18
bal = start; deb = 0.0; cred = 0.0; ok=True
for r in rows:
    a = float(r['amount']); b = float(r['balance'])
    if a<0: deb += -a
    else: cred += a
    bal = round(bal + a, 2)
    if abs(bal-b)>0.005:
        ok=False; print("balance break at", r['date'], r['description'], bal, b)
print("running balance continuous:", ok, "| ending:", round(bal,2))
print("total debits: %.2f (statement: 840417.07) | total credits: %.2f (statement: 509241.47)" % (deb, cred))
print("check: 212440.18 + 509241.47 - 840417.07 =", round(212440.18+509241.47-840417.07,2))

# categorize
def cat(d):
    t = d['description']
    if t.startswith('MERCHANT DEPOSIT'): return ('revenue',)
    if t == 'ACH DEBIT ADP PAYROLL': return ('payroll',)
    if t == 'ACH DEBIT ADP TAX': return ('other','payroll_taxes_adp')
    if 'PROPERTY MGMT RENT' in t: return ('rent',)
    if 'HENRY SCHEIN' in t or 'PATTERSON' in t: return ('supplies',)
    if 'DENTRIX' in t: return ('other','dentrix_software')
    if 'AUSTIN ENERGY' in t: return ('other','utilities_austin_energy')
    if 'SUMMIT SUPPLY' in t: return ('other','summit_supply_checks_flagged')
    raise ValueError(t)

months = {m: {'revenue':0.0,'payroll':0.0,'supplies':0.0,'rent':0.0,'other':defaultdict(float)} for m in ('01','02','03')}
parts = defaultdict(list)
for d in rows:
    m = d['date'][5:7]; a = float(d['amount']); c = cat(d)
    if len(c)==1: months[m][c[0]] += a
    else: months[m]['other'][c[1]] += a
    parts[(m,c)].append(a)

for m in months:
    for k in ('revenue','payroll','supplies','rent'):
        months[m][k] = round(months[m][k],2)
    months[m]['other'] = {k: round(v,2) for k,v in months[m]['other'].items()}
    tot_out = -sum(v for k,v in [(k,months[m][k]) for k in ('payroll','supplies','rent')] + list(months[m]['other'].items()))
    print(m, json.dumps(months[m]))
    print("   checks out (debits month):", round(tot_out,2))

print("\nShow-of-parts by month:")
for key in [('revenue',), ('payroll',), ('supplies',), ('rent',), ('other','payroll_taxes_adp'), ('other','dentrix_software'), ('other','utilities_austin_energy'), ('other','summit_supply_checks_flagged')]:
    for m in ('01','02','03'):
        ps = parts.get((m,key),[])
        print(" ", m, "/".join(key), "=", " + ".join(f"{p:.2f}" for p in ps), "= %.2f" % sum(ps))

# totals
for k in ('revenue','payroll','supplies','rent'):
    print("Q1 %s = %.2f" % (k, sum(months[m][k] for m in months)))
oq = defaultdict(float)
for m in months:
    for k,v in months[m]['other'].items(): oq[k]+=v
print("Q1 other =", {k:round(v,2) for k,v in oq.items()}, "| sum other = %.2f" % sum(oq.values()))
print("Q1 outflows total = %.2f" % (sum(months[m][k] for m in months for k in ('payroll','supplies','rent')) + sum(oq.values())))
EOF

